1: /* ==========================================================================
2:    Hero Component - Grace Fellowship Church
3:    Hero banner with clean deep navy gradient, Scripture verse, and CTA buttons
4:    Dynamically integrated with Church CMS API.
5:    ========================================================================== */
6: 
7: function Hero({ data }) {
8:   const handleScrollTo = (sectionId, e) => {
9:     if (sectionId && sectionId.startsWith("#")) {
10:       e.preventDefault();
11:       const elem = document.getElementById(sectionId.substring(1));
12:       if (elem) {
13:         elem.scrollIntoView({ behavior: "smooth" });
14:       }
15:     }
16:   };
17: 
18:   const welcomeText = data?.welcome_text || "Welcome to";
19:   const heroTitle = data?.hero_title || "Grace Fellowship Church";
20:   const heroSubtitle = data?.hero_subtitle || "A family of believers growing together in Christ's love.";
21:   const heroVerse = data?.hero_verse || "“For where two or three gather in my name, there am I with them.” — Matthew 18:20";
22:   const ctaPrimaryText = data?.cta_primary_text || "Join Us This Sunday";
23:   const ctaPrimaryLink = data?.cta_primary_link || "#service-timings";
24:   const ctaSecondaryText = data?.cta_secondary_text || "Watch Sermons";
25:   const ctaSecondaryLink = data?.cta_secondary_link || "#sermons";
26: 
27:   return (
28:     <section
29:       id="home"
30:       className="hero-section"
31:     >
32:       <div className="hero-overlay" />
33:       <div className="home-container" style={{ width: "100%" }}>
34:         <div className="hero-content">
35:           <p className="hero-welcome">{welcomeText}</p>
36:           <h1 className="hero-title">{heroTitle}</h1>
37:           <p className="hero-subtitle">{heroSubtitle}</p>
38:           <p className="hero-verse">{heroVerse}</p>
39: 
40:           <div className="hero-actions">
41:             <a
42:               href={ctaPrimaryLink}
43:               className="btn-hero-primary"
44:               onClick={(e) => handleScrollTo(ctaPrimaryLink, e)}
45:             >
46:               {ctaPrimaryText}
47:             </a>
48:             <a
49:               href={ctaSecondaryLink}
50:               className="btn-hero-secondary"
51:               onClick={(e) => handleScrollTo(ctaSecondaryLink, e)}
52:             >
53:               <span>▶</span>
54:               <span>{ctaSecondaryText}</span>
55:             </a>
56:           </div>
57:         </div>
58:       </div>
59:     </section>
60:   );
61: }

